// uart_log.v — the console log for the card.
//
// Emits a banner when a search starts and one line per hit:
//
//   ANUBIS v1<CR><LF>
//   HIT NONCE 0x0011223344556677 LZ 13<CR><LF>
//
// The text is generated by index instead of a string ROM, so there is nothing
// to initialise; add a message by extending the byte function.
`timescale 1ns/1ps
module uart_log #(
    parameter integer CLK_HZ = 50_000_000,
    parameter integer BAUD   = 115_200
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        ev_start,      // pulse: print the banner
    input  wire        ev_hit,        // pulse: print a hit line
    input  wire [63:0] nonce,
    input  wire [7:0]  lz,
    output wire        tx
);
    localparam integer BANNER_LEN = 11;
    localparam integer HIT_LEN    = 36;   // 12 + 16 + 4 + 2 + CRLF

    reg        tx_valid;
    reg  [7:0] tx_byte;
    wire       tx_ready;

    reg [1:0]  banner;        // 0 idle, 1 banner, 2 hit line
    reg [5:0]  idx;
    reg [63:0] nonce_r;
    reg [7:0]  lz_r;

    uart_tx #(.CLK_HZ(CLK_HZ), .BAUD(BAUD)) u_tx (
        .clk(clk), .rst_n(rst_n), .tx_valid(tx_valid), .tx_data(tx_byte),
        .tx_ready(tx_ready), .tx(tx));

    // ---- banner bytes -----------------------------------------------------
    function [7:0] banner_byte(input [5:0] k);
        begin
            case (k)
                6'd0: banner_byte = "A";
                6'd1: banner_byte = "N";
                6'd2: banner_byte = "U";
                6'd3: banner_byte = "B";
                6'd4: banner_byte = "I";
                6'd5: banner_byte = "S";
                6'd6: banner_byte = " ";
                6'd7: banner_byte = "v";
                6'd8: banner_byte = "1";
                6'd9: banner_byte = 8'h0D;
                default: banner_byte = 8'h0A;
            endcase
        end
    endfunction

    // ---- hit line: "HIT NONCE 0x" + 16 hex + " LZ " + 2 hex + CRLF --------
    function [7:0] hit_byte(input [5:0] k, input [63:0] n, input [7:0] z);
        reg [7:0] d;
        begin
            case (k)
                6'd0:  hit_byte = "H";
                6'd1:  hit_byte = "I";
                6'd2:  hit_byte = "T";
                6'd3:  hit_byte = " ";
                6'd4:  hit_byte = "N";
                6'd5:  hit_byte = "O";
                6'd6:  hit_byte = "N";
                6'd7:  hit_byte = "C";
                6'd8:  hit_byte = "E";
                6'd9:  hit_byte = " ";
                6'd10: hit_byte = "0";
                6'd11: hit_byte = "x";
                6'd28: hit_byte = " ";
                6'd29: hit_byte = "L";
                6'd30: hit_byte = "Z";
                6'd31: hit_byte = " ";
                6'd34: hit_byte = 8'h0D;
                6'd35: hit_byte = 8'h0A;
                default: begin
                    if (k < 6'd28) begin                    // nonce, 16 nibbles
                        d = ((n >> (4 * (27 - k))) & 64'hF) + 8'h30;
                        hit_byte = (d > 8'h39) ? (d + 8'd7) : d;
                    end else if (k == 6'd32) begin           // lz high nibble
                        d = ((z >> 4) & 4'hF) + 8'h30;
                        hit_byte = (d > 8'h39) ? (d + 8'd7) : d;
                    end else if (k == 6'd33) begin           // lz low nibble
                        d = (z & 4'hF) + 8'h30;
                        hit_byte = (d > 8'h39) ? (d + 8'd7) : d;
                    end else begin
                        hit_byte = " ";
                    end
                end
            endcase
        end
    endfunction

    wire [7:0] cur_byte = (banner == 2'd1) ? banner_byte(idx)
                                           : hit_byte(idx, nonce_r, lz_r);
    wire       last_byte = (banner == 2'd1) ? (idx == BANNER_LEN[5:0] - 6'd1)
                                           : (idx == HIT_LEN[5:0] - 6'd1);

    // Byte handshake: offer a byte, wait for the transmitter to take it, and
    // only then advance. Presenting and advancing in the same cycle loses every
    // other byte, because uart_tx samples tx_data on the cycle it accepts.
    always @(posedge clk) begin
        if (!rst_n) begin
            banner <= 2'd0; idx <= 6'd0; tx_valid <= 1'b0;
            tx_byte <= 8'd0; nonce_r <= 64'd0; lz_r <= 8'd0;
        end else if (banner == 2'd0) begin
            tx_valid <= 1'b0;
            if (ev_start) begin
                banner <= 2'd1; idx <= 6'd0;
            end else if (ev_hit) begin
                banner <= 2'd2; idx <= 6'd0;
                nonce_r <= nonce; lz_r <= lz;
            end
        end else if (!tx_valid) begin
            if (tx_ready) begin
                tx_valid <= 1'b1;
                tx_byte  <= cur_byte;
            end
        end else if (tx_ready) begin
            tx_valid <= 1'b0;
            if (last_byte) banner <= 2'd0;
            else idx <= idx + 6'd1;
        end
    end
endmodule
